const TZ = 'America/Sao_Paulo';
const GRUPO = '120363412854461070@g.us';
const NL = String.fromCharCode(10);
const agora = DateTime.now().setZone(TZ);
const hoje = agora.startOf('day');
const rows = n => { try { return $(n).all().map(i => i.json).filter(r => r && r.id != null); } catch (e) { return []; } };
const extras = rows('Carregar extras');
const txs = rows('Carregar transações');
const tarefas = rows('Carregar tarefas abertas');
const out = [];
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, '').trim();
const cap = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
const milhar = s => { let o = ''; for (let i = 0; i < s.length; i++) { if (i > 0 && (s.length - i) % 3 === 0) o += '.'; o += s[i]; } return o; };
const brl = v => { const n = Math.abs(Number(v || 0)).toFixed(2).split('.'); return (Number(v) < 0 ? '-' : '') + 'R$ ' + milhar(n[0]) + ',' + n[1]; };
const num = (v, d) => { if (v === null || v === undefined || v === '') return d; const n = Number(String(v).replace(',', '.')); return isNaN(n) ? d : n; };
const dados = r => { try { return JSON.parse(r.dados || '{}') || {}; } catch (e) { return {}; } };
const diaIso = v => { if (!v) return null; const d = DateTime.fromISO(String(v).slice(0, 10), { zone: TZ }); return d.isValid ? d.startOf('day') : null; };
const aut = r => r.autor || 'Daniel';
const msg = (numero, texto) => out.push({ json: { op: 'msg', numero, texto } });
const ins = (autor, tipo, titulo, texto, d, valor, data, status) => out.push({ json: { op: 'ins_extras', autor, tipo, titulo, texto: texto || '', dados: JSON.stringify(d || {}), valor: valor === undefined ? null : valor, data: data || null, status: status || 'ativa' } });
const upd = (r, ch) => { const base = { op: 'upd_extras', id: r.id, titulo: r.titulo, texto: r.texto || '', dados: r.dados || '{}', valor: r.valor === undefined ? null : r.valor, data: r.data || null, status: r.status || 'ativa' }; out.push({ json: Object.assign(base, ch) }); };
const dtx = v => DateTime.fromISO(String(v)).setZone(TZ);

const periodo = p0 => {
  const p = String(p0 || 'mes').toLowerCase();
  let ini, fim, rotulo;
  if (p === 'mes_passado') { ini = agora.minus({ months: 1 }).startOf('month'); fim = agora.startOf('month').minus({ milliseconds: 1 }); rotulo = 'em ' + MESES[ini.month - 1] + ' de ' + ini.year; }
  else if (p === 'semana') { ini = agora.startOf('week'); fim = agora.endOf('day'); rotulo = 'esta semana'; }
  else if (p === 'ultimos_30' || p === '30d') { ini = agora.minus({ days: 29 }).startOf('day'); fim = agora.endOf('day'); rotulo = 'nos últimos 30 dias'; }
  else if (p === 'ano') { ini = agora.startOf('year'); fim = agora.endOf('day'); rotulo = 'em ' + agora.year; }
  else { ini = agora.startOf('month'); fim = agora.endOf('day'); rotulo = 'em ' + MESES[agora.month - 1] + ' de ' + agora.year; }
  return { ini, fim, rotulo, chave: p };
};

// Lançamentos automáticos de parcelados e recorrentes
const rodar = r => {
  const d = dados(r);
  const lanc = [];
  let prox = diaIso(r.data);
  let guarda = 0;
  while (prox && prox <= hoje && guarda < 24 && (d.total === null || d.total === undefined || (d.feitas || 0) < d.total)) {
    d.feitas = (d.feitas || 0) + 1;
    const rot = d.total ? ' (' + d.feitas + '/' + d.total + ')' : '';
    out.push({ json: { op: 'ins_tx', movimento: d.movimento || 'despesa', valor: Number(r.valor), categoria: d.categoria || 'outros', descricao: r.titulo + rot, data: prox.set({ hour: 12 }).toUTC().toISO(), forma_pagamento: d.forma || '', autor: aut(r), comprovante_url: '' } });
    lanc.push(r.titulo + rot + ' ' + brl(r.valor));
    const nx = prox.plus({ months: 1 });
    prox = nx.set({ day: Math.min(d.dia || prox.day, nx.daysInMonth) });
    guarda++;
  }
  const fim = d.total !== null && d.total !== undefined && d.feitas >= d.total;
  return { d, prox, lanc, fim };
};

// Tarefas em atraso
const diasAtraso = t => Math.round(hoje.diff(dtx(t.prazo).startOf('day'), 'days').days);
const atrasadasDe = (autor, projeto) => tarefas.filter(t => aut(t) === autor && t.prazo && diasAtraso(t) > 0 && (!projeto || norm(t.projeto) === norm(projeto)));
const textoAtrasadas = (lista, intro) => {
  const ord = lista.slice().sort((a, b) => diasAtraso(b) - diasAtraso(a));
  const n = ord.length;
  let t = (intro || '') + n + (n === 1 ? ' tarefa em atraso' : ' tarefas em atraso') + ', a mais antiga há ' + diasAtraso(ord[0]) + (diasAtraso(ord[0]) === 1 ? ' dia.' : ' dias.');
  for (const x of ord.slice(0, 6)) t += NL + '• ' + x.titulo + (x.projeto ? ' [' + x.projeto + ']' : '') + ' — há ' + diasAtraso(x) + 'd (' + dtx(x.prazo).toFormat('dd/LL') + ')';
  if (n > 6) t += NL + '… e mais ' + (n - 6) + '.';
  return t;
};

const itens = [];
for (const it of $('Receber ação').all()) { if (it && it.json) itens.push(it.json); }

for (const it of itens) {
  const numero = it.numero;
  const autor = it.autor || 'Daniel';

  // Rotina diária (09:30): parcelas/recorrentes vencidos e aviso de tarefas atrasadas
  if (it.rotina) {
    const porAutor = {};
    for (const r of extras.filter(x => x.tipo === 'recorrente' && x.status === 'ativa')) {
      const rr = rodar(r);
      if (!rr.lanc.length) continue;
      upd(r, { dados: JSON.stringify(rr.d), data: rr.prox ? rr.prox.toUTC().toISO() : r.data, status: rr.fim ? 'encerrada' : 'ativa' });
      (porAutor[aut(r)] = porAutor[aut(r)] || []).push(...rr.lanc);
    }
    for (const [au, ls] of Object.entries(porAutor)) msg(GRUPO, au + ', lancei automaticamente hoje: ' + ls.join('; ') + '.');
    const autores = Array.from(new Set(tarefas.map(aut)));
    for (const au of autores) {
      const l = atrasadasDe(au, null);
      if (l.length) msg(GRUPO, textoAtrasadas(l, au + ', você tem '));
    }
    continue;
  }

  const a = it.a || {};
  const t = String(a.tipo || '');

  // ---------- Notas, listas e ideias ----------
  if (t === 'nota') {
    const op = String(a.op || 'ver');
    const mine = extras.filter(r => aut(r) === autor && (r.tipo === 'nota' || r.tipo === 'ideia') && r.status !== 'apagada');
    const nt = norm(a.titulo);
    const achar = () => nt ? (mine.find(r => norm(r.titulo) === nt) || mine.find(r => norm(r.titulo).includes(nt) || nt.includes(norm(r.titulo)))) : null;
    // Evita listas duplicadas: se a pessoa mexeu numa lista parecida na última 1h (mesmo assunto), usa a mesma.
    const PARADA = ['lista', 'listas', 'checklist', 'check', 'para', 'itens', 'item', 'compras', 'compra', 'levar', 'nota', 'notas', 'minha', 'meus', 'minhas'];
    const toks = s => norm(s).split(' ').filter(w => w.length > 3 && !PARADA.includes(w));
    const parecida = () => { const tk = toks(a.titulo); if (!tk.length) return null; const lim = agora.minus({ hours: 1 }); return mine.filter(r => DateTime.fromISO(String(r.updatedAt || r.createdAt)) >= lim).find(r => toks(r.titulo).some(w => tk.includes(w))) || null; };
    const lista = Array.isArray(a.itens) ? a.itens.map(x => String(x).trim()).filter(Boolean) : [];
    const itensDe = r => Array.isArray(dados(r).itens) ? dados(r).itens : [];
    const mostrar = r => {
      const its = itensDe(r);
      if (its.length) return '📝 *' + r.titulo + '*' + NL + its.map(x => '☐ ' + x).join(NL);
      return '*' + r.titulo + '*' + NL + (r.texto || '(vazia)');
    };
    if (op === 'criar' || op === 'adicionar') {
      const r = achar() || parecida();
      if (r) {
        const its = itensDe(r);
        if (lista.length) {
          const novos = lista.filter(x => !its.some(y => norm(y) === norm(x)));
          const todos = its.concat(novos);
          upd(r, { dados: JSON.stringify({ itens: todos }), status: 'ativa' });
          msg(numero, (novos.length ? 'Atualizei a lista (' + novos.length + (novos.length === 1 ? ' item novo).' : ' itens novos).') : 'Essa lista já tinha tudo isso.') + NL + NL + '📝 *' + r.titulo + '*' + NL + todos.map(x => '☐ ' + x).join(NL) + NL + NL + '_Para ver de novo: "me mostra a lista ' + r.titulo + '". Para riscar: "tira protetor da lista"._');
        } else if (a.texto) {
          upd(r, { texto: (r.texto ? r.texto + NL : '') + String(a.texto).slice(0, 2000), status: 'ativa' });
          msg(numero, 'Anotei em *' + r.titulo + '*.');
        } else msg(numero, 'O que você quer que eu adicione em *' + r.titulo + '*?');
      } else if (lista.length) {
        const titulo = String(a.titulo || 'Lista').slice(0, 80);
        ins(autor, 'nota', titulo, '', { itens: lista }, null, null, 'ativa');
        msg(numero, 'Criei a lista, com ' + lista.length + (lista.length === 1 ? ' item:' : ' itens:') + NL + NL + '📝 *' + titulo + '*' + NL + lista.map(x => '☐ ' + x).join(NL) + NL + NL + '_Para ver de novo: "me mostra a lista ' + titulo + '". Para riscar: "tira ' + lista[0].toLowerCase() + ' da lista"._');
      } else if (a.texto) {
        const titulo = String(a.titulo || String(a.texto).slice(0, 40)).slice(0, 80);
        ins(autor, a.formato === 'nota' ? 'nota' : 'ideia', titulo, String(a.texto).slice(0, 2000), {}, null, null, 'ativa');
        msg(numero, (a.formato === 'nota' ? 'Nota guardada: *' : 'Ideia guardada: *') + titulo + '*. Depois é só me perguntar sobre esse assunto.');
      }
    } else if (op === 'remover_item') {
      const r = achar();
      if (!r || !lista.length) { msg(numero, 'Não achei essa lista. Quer ver as suas?'); continue; }
      const its = itensDe(r);
      const resta = its.filter(x => !lista.some(y => norm(x).includes(norm(y)) && norm(y).length > 1));
      upd(r, { dados: JSON.stringify({ itens: resta }) });
      msg(numero, resta.length ? 'Riscado ✅' + NL + NL + '📝 *' + r.titulo + '*' + NL + resta.map(x => '☐ ' + x).join(NL) : 'Riscado ✅ A lista *' + r.titulo + '* está completa! 🎉');
    } else if (op === 'apagar') {
      const r = achar();
      if (!r) { msg(numero, 'Não achei essa nota para apagar.'); continue; }
      upd(r, { status: 'apagada' });
      msg(numero, 'Apaguei *' + r.titulo + '*.');
    } else if (op === 'buscar') {
      const toks = norm(a.busca || a.titulo).split(' ').filter(x => x.length > 2);
      const pont = mine.map(r => { const alvo = norm(r.titulo + ' ' + (r.texto || '') + ' ' + itensDe(r).join(' ')); let s = 0; for (const k of toks) if (alvo.includes(k) || alvo.includes(k.slice(0, Math.max(4, k.length - 2)))) s++; return { r, s }; }).filter(x => x.s > 0).sort((x, y) => y.s - x.s).slice(0, 5);
      if (!pont.length) msg(numero, 'Não achei nada sobre isso nas suas notas e ideias.');
      else msg(numero, 'Achei isso:' + NL + pont.map(x => '• *' + x.r.titulo + '* — ' + (itensDe(x.r).length ? itensDe(x.r).join(', ') : String(x.r.texto || '').slice(0, 140))).join(NL));
    } else {
      const r = achar();
      if (r) msg(numero, mostrar(r));
      else if (!nt && mine.length === 1) msg(numero, mostrar(mine[0]));
      else if (!mine.length) msg(numero, 'Você ainda não tem listas nem ideias guardadas.');
      else msg(numero, 'Suas notas:' + NL + mine.map(x => '• ' + x.titulo + (x.tipo === 'ideia' ? ' (ideia)' : '')).join(NL));
    }
    continue;
  }

  // ---------- Parcelados e recorrentes ----------
  if (t === 'criar_recorrente') {
    const valor = Math.abs(num(a.valor, 0));
    const desc = String(a.descricao || '').trim().slice(0, 120);
    if (!valor || !desc) { msg(numero, 'Para criar o lançamento automático preciso da descrição e do valor.'); continue; }
    let total = (a.parcelas === null || a.parcelas === undefined || a.parcelas === '') ? null : Math.round(num(a.parcelas, 0));
    if (total !== null) total = Math.max(1, Math.min(60, total));
    const ja = Math.max(0, Math.round(num(a.ja_pagas, 0)));
    const prim = diaIso(a.primeira_data) || hoje;
    const row = { titulo: desc, valor, data: prim.toUTC().toISO(), autor, dados: JSON.stringify({ total, feitas: ja, movimento: a.movimento === 'receita' ? 'receita' : 'despesa', categoria: String(a.categoria || 'outros').toLowerCase(), forma: String(a.forma_pagamento || ''), dia: prim.day }) };
    const rr = rodar(row);
    ins(autor, 'recorrente', desc, '', rr.d, valor, rr.prox ? rr.prox.toUTC().toISO() : null, rr.fim ? 'encerrada' : 'ativa');
    msg(numero, 'Combinado! *' + desc + '*: ' + brl(valor) + (total ? ' em ' + total + ' parcelas' : ' todo mês') + '.' + (rr.lanc.length ? ' Já lancei: ' + rr.lanc.join(', ') + '.' : '') + (rr.fim ? ' Todas as parcelas já estavam lançadas.' : ' Próximo lançamento automático em ' + rr.prox.toFormat('dd/LL/yyyy') + '.'));
    continue;
  }
  if (t === 'cancelar_recorrente') {
    const nt = norm(a.titulo);
    const r = extras.find(x => x.tipo === 'recorrente' && aut(x) === autor && x.status === 'ativa' && nt && (norm(x.titulo).includes(nt) || nt.includes(norm(x.titulo))));
    if (!r) { msg(numero, 'Não achei esse lançamento automático ativo.'); continue; }
    upd(r, { status: 'cancelada' });
    msg(numero, 'Cancelei o lançamento automático de *' + r.titulo + '*. O que já foi lançado continua no histórico.');
    continue;
  }
  if (t === 'listar_recorrentes') {
    const l = extras.filter(x => x.tipo === 'recorrente' && aut(x) === autor && x.status === 'ativa');
    if (!l.length) { msg(numero, 'Você não tem parcelados nem recorrentes ativos.'); continue; }
    msg(numero, 'Seus lançamentos automáticos:' + NL + l.map(r => { const d = dados(r); const falta = d.total ? (d.total - (d.feitas || 0)) + ' parcelas restantes' : 'sem fim'; return '• *' + r.titulo + '* — ' + brl(r.valor) + ', ' + falta + ', próximo ' + dtx(r.data).toFormat('dd/LL'); }).join(NL));
    continue;
  }

  // ---------- Clientes e contas a receber ----------
  if (t === 'cadastrar_cliente') {
    const nome = String(a.nome || '').trim().slice(0, 120);
    if (!nome) continue;
    const ex = extras.find(x => x.tipo === 'cliente' && aut(x) === autor && norm(x.titulo) === norm(nome));
    const d = { documento: String(a.documento || ''), papel: a.papel === 'fornecedor' ? 'fornecedor' : 'cliente', telefone: String(a.telefone || ''), obs: String(a.obs || '') };
    if (ex) { upd(ex, { dados: JSON.stringify(Object.assign(dados(ex), d)) }); msg(numero, 'Atualizei o cadastro de *' + nome + '*.'); }
    else { ins(autor, 'cliente', nome, '', d, null, null, 'ativa'); msg(numero, (d.papel === 'fornecedor' ? 'Fornecedor' : 'Cliente') + ' cadastrado: *' + nome + '*.'); }
    continue;
  }
  if (t === 'criar_recebivel') {
    const valor = Math.abs(num(a.valor, 0));
    const dev = String(a.devedor || '').trim().slice(0, 120);
    if (!valor || !dev) { msg(numero, 'Para anotar o que te devem preciso do nome e do valor.'); continue; }
    const venc = diaIso(a.vencimento);
    ins(autor, 'recebivel', dev, String(a.motivo || '').slice(0, 200), { origem: 'manual' }, valor, venc ? venc.toUTC().toISO() : null, 'aberto');
    msg(numero, 'Anotado: *' + dev + '* te deve ' + brl(valor) + (a.motivo ? ' (' + a.motivo + ')' : '') + (venc ? ', vence em ' + venc.toFormat('dd/LL/yyyy') : '') + '.');
    continue;
  }
  if (t === 'quem_deve') {
    const ab = extras.filter(x => x.tipo === 'recebivel' && aut(x) === autor && x.status === 'aberto');
    if (!ab.length) { msg(numero, 'Ninguém está te devendo nada por aqui.'); continue; }
    const g = {};
    for (const r of ab) { const k = r.titulo; g[k] = g[k] || { total: 0, atraso: 0 }; g[k].total += Number(r.valor) || 0; if (r.data) { const dd = Math.round(hoje.diff(dtx(r.data).startOf('day'), 'days').days); if (dd > g[k].atraso) g[k].atraso = dd; } }
    const ls = Object.entries(g).sort((x, y) => y[1].total - x[1].total);
    const tot = ls.reduce((s, x) => s + x[1].total, 0);
    msg(numero, 'Te devem ' + brl(tot) + ':' + NL + ls.map(x => '• *' + x[0] + '* — ' + brl(x[1].total) + (x[1].atraso > 0 ? ' (atrasado há ' + x[1].atraso + ' dias)' : '')).join(NL));
    continue;
  }
  if (t === 'receber_recebivel') {
    const nd = norm(a.devedor);
    const ab = extras.filter(x => x.tipo === 'recebivel' && aut(x) === autor && x.status === 'aberto' && nd && (norm(x.titulo).includes(nd) || nd.includes(norm(x.titulo)))).sort((x, y) => x.id - y.id);
    if (!ab.length) { msg(numero, 'Não achei nada em aberto com esse nome.'); continue; }
    let resta = Math.abs(num(a.valor, 0)) || ab.reduce((s, x) => s + Number(x.valor), 0);
    const recebido = resta;
    for (const r of ab) {
      if (resta <= 0) break;
      const v = Number(r.valor) || 0;
      if (resta >= v - 0.005) { upd(r, { status: 'pago', data: r.data }); resta -= v; }
      else { upd(r, { valor: Math.round((v - resta) * 100) / 100 }); resta = 0; }
    }
    out.push({ json: { op: 'ins_tx', movimento: 'receita', valor: recebido, categoria: 'recebimentos', descricao: 'Recebido de ' + ab[0].titulo, data: agora.toUTC().toISO(), forma_pagamento: String(a.forma_pagamento || ''), autor, comprovante_url: '' } });
    msg(numero, 'Baixei ' + brl(recebido) + ' de *' + ab[0].titulo + '* e lancei como receita.');
    continue;
  }
  if (t === 'consultar_cliente') {
    const nm = norm(a.nome);
    if (!nm) continue;
    const p = periodo(a.periodo);
    const rel = txs.filter(x => aut(x) === autor && norm(x.descricao).includes(nm) && dtx(x.data) >= p.ini && dtx(x.data) <= p.fim);
    const rec = rel.filter(x => x.tipo === 'receita');
    const des = rel.filter(x => x.tipo !== 'receita');
    const soma = l => l.reduce((s, x) => s + Number(x.valor || 0), 0);
    const ab = extras.filter(x => x.tipo === 'recebivel' && aut(x) === autor && x.status === 'aberto' && norm(x.titulo).includes(nm));
    const cad = extras.find(x => x.tipo === 'cliente' && aut(x) === autor && (norm(x.titulo).includes(nm) || nm.includes(norm(x.titulo))));
    const nomeShow = cad ? cad.titulo : cap(String(a.nome));
    const partes = [];
    if (rec.length) partes.push('Você recebeu ' + brl(soma(rec)) + ' de *' + nomeShow + '* ' + p.rotulo + ', em ' + rec.length + (rec.length === 1 ? ' pagamento.' : ' pagamentos.'));
    if (des.length) partes.push('E pagou ' + brl(soma(des)) + ' a *' + nomeShow + '* no período, em ' + des.length + (des.length === 1 ? ' lançamento.' : ' lançamentos.'));
    if (!partes.length) partes.push('Não encontrei lançamentos de *' + nomeShow + '* ' + p.rotulo + '. (Eu procuro o nome na descrição do lançamento.)');
    if (ab.length) partes.push('Ainda tem ' + brl(soma(ab)) + ' em aberto dele(a).');
    msg(numero, partes.join(' '));
    continue;
  }

  // ---------- Desfazer / editar último lançamento (24h) ----------
  if (t === 'desfazer_ultimo' || t === 'editar_ultimo') {
    const mine = txs.filter(x => aut(x) === autor && x.createdAt && agora.diff(dtx(x.createdAt), 'hours').hours <= 24).sort((x, y) => Number(y.id) - Number(x.id));
    if (!mine.length) { msg(numero, 'Não achei nenhum lançamento seu nas últimas 24 horas para ' + (t === 'desfazer_ultimo' ? 'desfazer.' : 'ajustar.')); continue; }
    const l = mine[0];
    const resumo = (l.tipo === 'receita' ? 'receita' : 'despesa') + ' de ' + brl(l.valor) + ' em ' + (l.categoria || 'outros') + (l.descricao ? ' (' + l.descricao + ')' : '');
    if (t === 'desfazer_ultimo') {
      out.push({ json: { op: 'del_tx', id: l.id, autor } });
      msg(numero, 'Desfeito: ' + resumo + '.');
    } else {
      const novo = { id: l.id, autor, tipo: a.movimento === 'receita' || a.movimento === 'despesa' ? a.movimento : l.tipo, valor: Math.abs(num(a.valor, Number(l.valor))), categoria: a.categoria ? String(a.categoria).toLowerCase() : l.categoria, descricao: a.descricao ? String(a.descricao) : (l.descricao || ''), data: a.data && DateTime.fromISO(String(a.data)).isValid ? DateTime.fromISO(String(a.data), { zone: TZ }).toUTC().toISO() : l.data, forma_pagamento: a.forma_pagamento ? String(a.forma_pagamento) : (l.forma_pagamento || '') };
      out.push({ json: Object.assign({ op: 'upd_tx' }, novo) });
      msg(numero, 'Ajustei: agora é ' + (novo.tipo === 'receita' ? 'receita' : 'despesa') + ' de ' + brl(novo.valor) + ' em ' + (novo.categoria || 'outros') + (novo.descricao ? ' (' + novo.descricao + ')' : '') + '.');
    }
    continue;
  }

  // ---------- Convites ----------
  if (t === 'gerar_convite') {
    const alfa = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let cod = 'DYNO-';
    for (let i = 0; i < 6; i++) cod += alfa.charAt(Math.floor(Math.random() * alfa.length));
    const exp = hoje.plus({ days: 7 });
    ins(autor, 'convite', cod, '', { para: String(a.nome || '') }, null, exp.toUTC().toISO(), 'aberto');
    msg(numero, 'Convite criado: *' + cod + '*' + (a.nome ? ' (para ' + a.nome + ')' : '') + '. Vale até ' + exp.toFormat('dd/LL/yyyy') + '. Quem receber usa esse código para entrar na sua conta, sem pagar a mais.');
    continue;
  }
  if (t === 'listar_convites') {
    const l = extras.filter(x => x.tipo === 'convite' && aut(x) === autor && x.status === 'aberto' && (!x.data || dtx(x.data) >= hoje));
    msg(numero, l.length ? 'Convites abertos:' + NL + l.map(x => '• *' + x.titulo + '*' + (dados(x).para ? ' (' + dados(x).para + ')' : '') + ' — até ' + dtx(x.data).toFormat('dd/LL')).join(NL) : 'Você não tem convites abertos.');
    continue;
  }
  if (t === 'revogar_convite') {
    const cod = String(a.codigo || '').toUpperCase().trim();
    const r = extras.find(x => x.tipo === 'convite' && aut(x) === autor && x.titulo === cod && x.status === 'aberto');
    if (!r) { msg(numero, 'Não achei esse convite aberto.'); continue; }
    upd(r, { status: 'revogado' });
    msg(numero, 'Convite *' + cod + '* cancelado.');
    continue;
  }
  if (t === 'resgatar_convite') {
    const cod = String(a.codigo || '').toUpperCase().trim();
    const r = extras.find(x => x.tipo === 'convite' && x.titulo === cod && x.status === 'aberto' && (!x.data || dtx(x.data) >= hoje));
    if (!r) { msg(numero, 'Esse código de convite não existe, já foi usado ou expirou.'); continue; }
    upd(r, { status: 'usado', dados: JSON.stringify(Object.assign(dados(r), { usado_por: String(a.nome || ''), numero, em: agora.toISO() })) });
    ins(r.autor || 'Daniel', 'participante', String(a.nome || numero), numero, { convite: cod }, null, agora.toUTC().toISO(), 'ativo');
    msg(numero, 'Prontinho' + (a.nome ? ', ' + a.nome : '') + '! Sua conta foi conectada à de ' + (r.autor || 'Daniel') + '.');
    continue;
  }

  // ---------- Relatório em Excel (+ dashboard em imagem) ----------
  if (t === 'relatorio_excel') {
    const p = periodo(a.periodo);
    const mine = txs.filter(x => aut(x) === autor && dtx(x.data) >= p.ini && dtx(x.data) <= p.fim).sort((x, y) => dtx(x.data).toMillis() - dtx(y.data).toMillis());
    if (!mine.length) { msg(numero, 'Não encontrei lançamentos seus ' + p.rotulo + ' para montar o relatório.'); continue; }
    const linhas = mine.map(x => ({ 'Data': dtx(x.data).toFormat('dd/LL/yyyy'), 'Descrição': x.descricao || '', 'Categoria': cap(String(x.categoria || 'outros')), 'Tipo': x.tipo === 'receita' ? 'Receita' : 'Despesa', 'Forma de pagamento': x.forma_pagamento || '', 'Valor': Number(Number(x.valor || 0).toFixed(2)) }));
    const totD = mine.filter(x => x.tipo !== 'receita').reduce((s, x) => s + Number(x.valor || 0), 0);
    const totR = mine.filter(x => x.tipo === 'receita').reduce((s, x) => s + Number(x.valor || 0), 0);
    linhas.push({ 'Data': '', 'Descrição': '', 'Categoria': '', 'Tipo': '', 'Forma de pagamento': '', 'Valor': '' });
    linhas.push({ 'Data': '', 'Descrição': 'TOTAL DE DESPESAS', 'Categoria': '', 'Tipo': '', 'Forma de pagamento': '', 'Valor': Number(totD.toFixed(2)) });
    linhas.push({ 'Data': '', 'Descrição': 'TOTAL DE RECEITAS', 'Categoria': '', 'Tipo': '', 'Forma de pagamento': '', 'Valor': Number(totR.toFixed(2)) });
    linhas.push({ 'Data': '', 'Descrição': 'SALDO', 'Categoria': '', 'Tipo': '', 'Forma de pagamento': '', 'Valor': Number((totR - totD).toFixed(2)) });
    out.push({ json: { op: 'excel', numero, autor, linhas, caption: '📎 Relatório (Excel) ' + p.rotulo + NL + mine.length + ' lançamentos · Despesas ' + brl(totD) + ' · Receitas ' + brl(totR) } });
    out.push({ json: { op: 'dash', numero, autor, periodo: p.chave } });
    continue;
  }

  // ---------- Tarefas: projeto e atrasadas ----------
  if (t === 'definir_projeto') {
    const id = Number(a.id);
    const r = tarefas.find(x => Number(x.id) === id && aut(x) === autor);
    if (!r) { msg(numero, 'Não achei essa tarefa.'); continue; }
    const proj = String(a.projeto || '').trim().slice(0, 80);
    out.push({ json: { op: 'upd_tarefa', id, autor, projeto: proj } });
    msg(numero, proj ? 'Coloquei *' + r.titulo + '* no projeto *' + proj + '*.' : 'Tirei *' + r.titulo + '* do projeto.');
    continue;
  }
  if (t === 'ver_tarefas') {
    const proj = a.projeto ? String(a.projeto) : null;
    if (proj) {
      const l = tarefas.filter(x => aut(x) === autor && norm(x.projeto) === norm(proj));
      if (!l.length) { msg(numero, 'Não achei tarefas abertas no projeto *' + proj + '*.'); continue; }
      const atr = l.filter(x => x.prazo && diasAtraso(x) > 0).length;
      msg(numero, 'Projeto *' + proj + '*: ' + l.length + ' abertas' + (atr ? ', ' + atr + ' em atraso' : '') + '.' + NL + l.slice(0, 10).map(x => '• ' + x.titulo + (x.prazo ? ' — ' + (diasAtraso(x) > 0 ? 'atrasada há ' + diasAtraso(x) + 'd' : 'prazo ' + dtx(x.prazo).toFormat('dd/LL')) : '')).join(NL));
    } else {
      const l = atrasadasDe(autor, null);
      msg(numero, l.length ? textoAtrasadas(l, 'Você tem ') : 'Nenhuma tarefa em atraso. 👏');
    }
    continue;
  }
}
return out;

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const m = $('Processar').all().map(i => i.json).find(j => j.op === 'excel') || {};
return [{ json: { numero: m.numero, caption: m.caption, b64: buf.toString('base64') } }];

// Na rotina diária (09:30), as mensagens saem como "Nome, ..." para o grupo da família.
// Família continua no grupo; clientes do piloto recebem no privado (destinos vem do Supabase); quem não está no cadastro não recebe.
const FAMS = ['Daniel', 'Quézia', 'Eliezer'];
const GRUPO = '120363412854461070@g.us';
let pedido = {};
try { pedido = $('Receber ação').first().json || {}; } catch (e) { pedido = {}; }
if (!pedido.rotina) return $input.all();
const dest = (pedido.destinos && typeof pedido.destinos === 'object') ? pedido.destinos : {};
const nomes = Array.from(new Set([...FAMS, ...Object.keys(dest)])).sort((a, b) => b.length - a.length);
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.op !== 'msg' || j.numero !== GRUPO) { out.push(it); continue; }
