// Novas funções do Dyno/Dina: editar/apagar, previsão do mês, categorias próprias, metas, agenda.
// Passa todos os itens do "Processar" adiante e acrescenta os novos.
const TZ = 'America/Sao_Paulo';
const GRUPO = '120363412854461070@g.us';
const NL = String.fromCharCode(10);
const agora = DateTime.now().setZone(TZ);
const hoje = agora.startOf('day');
const out = $input.all().slice();
const rows = n => { try { return $(n).all().map(i => i.json).filter(r => r && r.id != null); } catch (e) { return []; } };
const extras = rows('Carregar extras');
const txs = rows('Carregar transações');
const tarefas = rows('Carregar tarefas abertas');
let nd = {};
try { nd = $('Carregar dados novos').first().json || {}; } catch (e) { nd = {}; }
const L = k => Array.isArray(nd[k]) ? nd[k] : [];
const lembretes = L('lembretes'), contas = L('contas'), assinaturas = L('assinaturas'), metas = L('metas'), compromissos = L('compromissos'), regras = L('regras');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, '').trim();
const milhar = s => { let o = ''; for (let i = 0; i < s.length; i++) { if (i > 0 && (s.length - i) % 3 === 0) o += '.'; o += s[i]; } return o; };
const brl = v => { const n = Math.abs(Number(v || 0)).toFixed(2).split('.'); return (Number(v) < 0 ? '-' : '') + 'R$ ' + milhar(n[0]) + ',' + n[1]; };
const num = (v, d) => { if (v === null || v === undefined || v === '') return d; const n = Number(String(v).replace(',', '.')); return isNaN(n) ? d : n; };
const aut = r => r.autor || 'Daniel';
const dt = v => DateTime.fromISO(String(v)).setZone(TZ);
const diaIso = v => { if (!v) return null; const d = DateTime.fromISO(String(v)).setZone(TZ); return d.isValid ? d.startOf('day') : null; };
const msg = (numero, texto) => out.push({ json: { op: 'msg', numero, texto } });
const ins = (tabela, corpo) => out.push({ json: { op: 'ins_sb', tabela, corpo } });
const pat = (tabela, id, autor, campos) => out.push({ json: { op: 'pat_sb', tabela, id, autor, campos } });
const rpc = (fn, args) => out.push({ json: { op: 'rpc_sb', fn, args } });
const upd = (r, ch) => { const base = { op: 'upd_extras', id: r.id, titulo: r.titulo, texto: r.texto || '', dados: r.dados || '{}', valor: r.valor === undefined ? null : r.valor, data: r.data || null, status: r.status || 'ativa' }; out.push({ json: Object.assign(base, ch) }); };
const parseDt = v => { if (!v) return null; const d = DateTime.fromISO(String(v), { zone: TZ }); return d.isValid ? d : null; };
const fmtDH = d => d.toFormat('dd/LL') + ' às ' + d.toFormat('HH:mm');
const DS = ['seg', 'ter', 'qua', 'qui', 'sex', 'sáb', 'dom'];

// Metas: progresso e valor semanal necessário
const linhaMeta = m => {
  const alvo = Number(m.valor_alvo), at = Number(m.valor_atual || 0);
  const pct = alvo > 0 ? Math.min(100, Math.round(at / alvo * 100)) : 0;
  let s = '• *' + m.titulo + '*: ' + brl(at) + ' de ' + brl(alvo) + ' (' + pct + '%)';
  const pz = diaIso(m.prazo);
  if (pz) {
    const sem = Math.max(1, Math.ceil(pz.diff(hoje, 'days').days / 7));
    const falta = Math.max(0, alvo - at);
    s += ' — prazo ' + pz.toFormat('dd/LL/yyyy') + (falta > 0 ? ', precisa guardar ~' + brl(falta / sem) + ' por semana' : '');
  }
  return s;
};

const itens = [];
for (const it of $('Receber ação').all()) { if (it && it.json) itens.push(it.json); }

for (const it of itens) {
  const numero = it.numero;
  const autor = it.autor || 'Daniel';

  // Rotina: toda segunda-feira, resumo das metas de cada pessoa
  if (it.rotina) {
    if (agora.weekday === 1) {
      const por = {};
      for (const m of metas) (por[aut(m)] = por[aut(m)] || []).push(m);
      for (const [au, ms] of Object.entries(por)) msg(GRUPO, au + ', suas metas:' + NL + ms.map(linhaMeta).join(NL));
    }
    continue;
  }

  const a = it.a || {};
  const t = String(a.tipo || '');

  // ---------- Editar lembrete ----------
  if (t === 'editar_lembrete') {
    const r = lembretes.find(x => Number(x.id) === Number(a.id) && aut(x) === autor);
    if (!r) { msg(numero, 'Não achei esse lembrete pendente.'); continue; }
    if (r.conta_id) { msg(numero, 'Esse lembrete é de uma conta a pagar. Para mudar, ajuste a própria conta.'); continue; }
    const ch = { status: 'pendente', insistencias: 0, proxima: null, msg_id: null, msg_jid: null };
    if (a.texto) ch.texto = String(a.texto).slice(0, 300);
    const q = parseDt(a.quando);
    if (a.quando && !q) { msg(numero, 'Não entendi o novo horário. Pode repetir com dia e hora?'); continue; }
    if (q) ch.quando = q.toUTC().toISO();
    if (a.recorrencia) ch.recorrencia = String(a.recorrencia);
    pat('dyno_lembretes', r.id, autor, ch);
    msg(numero, 'Lembrete atualizado: *' + (ch.texto || r.texto) + '* — ' + fmtDH(q || dt(r.quando)) + '.');
    continue;
  }

  // ---------- Editar / apagar tarefa ----------
  if (t === 'editar_tarefa' || t === 'apagar_tarefa') {
    const r = tarefas.find(x => Number(x.id) === Number(a.id) && aut(x) === autor);
    if (!r) { msg(numero, 'Não achei essa tarefa aberta.'); continue; }
    if (t === 'apagar_tarefa') { pat('dyno_tarefas', r.id, autor, { status: 'cancelada' }); msg(numero, 'Apaguei a tarefa *' + r.titulo + '*.'); continue; }
    const ch = {};
    if (a.titulo) ch.titulo = String(a.titulo).slice(0, 200);
    if (a.prioridade && ['alta', 'media', 'baixa'].includes(String(a.prioridade))) ch.prioridade = String(a.prioridade);
    if (a.notas) ch.notas = String(a.notas).slice(0, 500);
    if (a.prazo) { const p = parseDt(a.prazo); if (!p) { msg(numero, 'Não entendi o novo prazo.'); continue; } ch.prazo = p.toUTC().toISO(); }
    if (!Object.keys(ch).length) { msg(numero, 'O que você quer mudar nessa tarefa?'); continue; }
    pat('dyno_tarefas', r.id, autor, ch);
    msg(numero, 'Tarefa atualizada: *' + (ch.titulo || r.titulo) + '*' + (ch.prazo ? ' — prazo ' + dt(ch.prazo).toFormat('dd/LL') : '') + '.');
    continue;
  }

  // ---------- Editar nota ----------
  if (t === 'editar_nota') {
    const mine = extras.filter(r => aut(r) === autor && (r.tipo === 'nota' || r.tipo === 'ideia') && r.status !== 'apagada');
    const nt = norm(a.titulo);
    const r = nt ? (mine.find(x => norm(x.titulo) === nt) || mine.find(x => norm(x.titulo).includes(nt) || nt.includes(norm(x.titulo)))) : null;
    if (!r) { msg(numero, 'Não achei essa nota.'); continue; }
    const ch = {};
    if (a.novo_titulo) ch.titulo = String(a.novo_titulo).slice(0, 120);
    if (a.texto !== undefined && a.texto !== null && a.texto !== '') ch.texto = String(a.texto);
    if (!Object.keys(ch).length) { msg(numero, 'O que você quer mudar nessa nota?'); continue; }
    upd(r, ch);
    msg(numero, 'Nota atualizada: *' + (ch.titulo || r.titulo) + '*.');
    continue;
  }

  // ---------- Previsão do mês ----------
  if (t === 'previsao_mes') {
    const ini = agora.startOf('month'), fim = agora.endOf('month');
    const dia = agora.day, total = agora.daysInMonth, resta = total - dia;
    const doMes = txs.filter(x => aut(x) === autor && x.data && dt(x.data) >= ini && dt(x.data) <= agora);
    const des = doMes.filter(x => x.tipo !== 'receita');
    const gasto = des.reduce((s, x) => s + Number(x.valor || 0), 0);
    const receb = doMes.filter(x => x.tipo === 'receita').reduce((s, x) => s + Number(x.valor || 0), 0);
    const fixo = x => ['contas', 'assinaturas'].includes(norm(x.categoria)) || /^conta:/i.test(String(x.descricao || '')) || /\(\d+\/\d+\)/.test(String(x.descricao || ''));
    const variavel = des.filter(x => !fixo(x)).reduce((s, x) => s + Number(x.valor || 0), 0);
    const projVar = variavel / Math.max(1, dia) * resta;
    let aVencer = 0; const itensV = [];
    for (const c of contas.filter(x => aut(x) === autor)) { const v = diaIso(c.vencimento); if (v && v >= hoje && v <= fim) { aVencer += Number(c.valor || 0); itensV.push(c.descricao); } }
    for (const s of assinaturas.filter(x => aut(x) === autor)) { const v = diaIso(s.proxima_cobranca); if (v && v > hoje && v <= fim) { aVencer += Number(s.valor || 0); itensV.push(s.nome); } }
    for (const r of extras.filter(x => aut(x) === autor && x.tipo === 'recorrente' && x.status === 'ativa')) { const v = diaIso(r.data); if (v && v > hoje && v <= fim) { aVencer += Number(r.valor || 0); itensV.push(r.titulo); } }
    const prev = gasto + projVar + aVencer;
    let s = '📈 *Previsão de ' + agora.toFormat('LL/yyyy') + '* (estimativa)' + NL;
    s += '• Gasto até agora: ' + brl(gasto) + NL;
    s += '• Contas/assinaturas/parcelas a vencer: ' + brl(aVencer) + (itensV.length ? ' (' + itensV.slice(0, 5).join(', ') + ')' : '') + NL;
    s += '• Gastos do dia a dia no ritmo atual (' + resta + ' dias restantes): ' + brl(projVar) + NL;
    s += '*Total previsto no mês: ' + brl(prev) + '*';
    if (receb > 0) s += NL + 'Recebido no mês: ' + brl(receb) + ' → saldo previsto ' + brl(receb - prev) + '.';
    if (dia < 5) s += NL + '⚠️ Ainda é começo do mês, então a estimativa pode variar bastante.';
    msg(numero, s);
    continue;
  }

  // ---------- Categorias próprias ----------
  if (t === 'regra_categoria') {
    const padrao = norm(a.padrao), cat = String(a.categoria || '').toLowerCase().trim();
    if (!padrao || !cat) { msg(numero, 'Me diga a palavra e a categoria. Ex.: "mercado do João é alimentação".'); continue; }
    if (['receita', 'despesa', 'gasto', 'compra', 'venda', 'pix', 'pagamento', 'transferencia', 'entrada', 'saida', 'outros'].includes(padrao)) { msg(numero, 'Essa palavra é muito genérica para virar regra (pegaria quase todo lançamento). Me diga algo mais específico, como o nome da loja ou "dividendo".'); continue; }
    const ex = regras.find(r => aut(r) === autor && norm(r.padrao) === padrao);
    if (ex) pat('dyno_regras_categoria', ex.id, autor, { categoria: cat, ativo: true }); else ins('dyno_regras_categoria', { autor, padrao, categoria: cat });
    msg(numero, 'Combinado: lançamentos com *' + padrao + '* vão para a categoria *' + cat + '*.');
    continue;
  }
  if (t === 'listar_regras') {
    const mine = regras.filter(r => aut(r) === autor);
    msg(numero, mine.length ? 'Suas regras de categoria:' + NL + mine.map(r => '• ' + r.padrao + ' → ' + r.categoria).join(NL) : 'Você ainda não tem regras de categoria. Diga, por exemplo: "padaria é alimentação".');
    continue;
  }
  if (t === 'apagar_regra') {
    const p = norm(a.padrao);
    const r = regras.find(x => aut(x) === autor && (norm(x.padrao) === p || (p && norm(x.padrao).includes(p))));
    if (!r) { msg(numero, 'Não achei essa regra.'); continue; }
    pat('dyno_regras_categoria', r.id, autor, { ativo: false });
    msg(numero, 'Regra removida: ' + r.padrao + ' → ' + r.categoria + '.');
    continue;
  }
  // Aprender com correções: ao ajustar a categoria do último lançamento, cria a regra
  if (t === 'editar_ultimo' && a.categoria) {
    const mine = txs.filter(x => aut(x) === autor && x.createdAt && agora.diff(dt(x.createdAt), 'hours').hours <= 24).sort((x, y) => Number(y.id) - Number(x.id));
    const l = mine[0];
    if (l && l.descricao && norm(l.categoria) !== norm(a.categoria)) {
      const padrao = norm(l.descricao).split(' ').filter(Boolean).slice(0, 3).join(' ');
      const cat = String(a.categoria).toLowerCase().trim();
      // 08/10: não aprende regra com palavra genérica (ex.: "receita" virou regra para tudo em 07/10).
      const GENERICAS = ['receita', 'despesa', 'gasto', 'gastos', 'compra', 'compras', 'venda', 'vendas', 'pix', 'pagamento', 'transferencia', 'entrada', 'saida', 'outros', 'outro', 'credito', 'debito', 'cartao', 'dinheiro', 'valor', 'conta', 'contas', 'recebido', 'recebimento', 'deposito', 'lancamento', 'ajuste', 'de', 'do', 'da', 'no', 'na', 'em', 'e'];
      const generico = padrao.split(' ').every(w => GENERICAS.includes(w));
      if (padrao.length >= 4 && !generico && !regras.find(r => aut(r) === autor && norm(r.padrao) === padrao)) {
        ins('dyno_regras_categoria', { autor, padrao, categoria: cat });
        msg(numero, '🧠 Aprendi: lançamentos com *' + padrao + '* agora vão para *' + cat + '*. Para desfazer, diga "apagar regra ' + padrao + '".');
      }
    }
    continue;
  }

  // ---------- Metas ----------
  if (t === 'criar_meta') {
    const alvo = num(a.valor_alvo, 0), tit = String(a.titulo || '').trim().slice(0, 100);
    if (!tit || alvo <= 0) { msg(numero, 'Me diga o nome e o valor da meta. Ex.: "meta viagem 5000 até dezembro".'); continue; }
    const pz = parseDt(a.prazo);
    ins('dyno_metas', { autor, titulo: tit, valor_alvo: alvo, valor_atual: Math.max(0, num(a.valor_atual, 0)), prazo: pz ? pz.toFormat('yyyy-LL-dd') : null });
    msg(numero, '🎯 Meta criada: *' + tit + '* — ' + brl(alvo) + (pz ? ', até ' + pz.toFormat('dd/LL/yyyy') + ' (~' + brl(alvo / Math.max(1, Math.ceil(pz.diff(hoje, 'days').days / 7))) + ' por semana)' : '') + '. Para guardar, diga "guardei 200 na meta ' + tit + '".');
    continue;
  }
  if (t === 'guardar_meta' || t === 'apagar_meta') {
    const nt = norm(a.titulo);
    const mine = metas.filter(m => aut(m) === autor);
    const m = nt ? (mine.find(x => norm(x.titulo) === nt) || mine.find(x => norm(x.titulo).includes(nt) || nt.includes(norm(x.titulo)))) : (mine.length === 1 ? mine[0] : null);
    if (!m) { msg(numero, 'Não achei essa meta.' + (mine.length ? ' Suas metas: ' + mine.map(x => x.titulo).join(', ') + '.' : '')); continue; }
    if (t === 'apagar_meta') { pat('dyno_metas', m.id, autor, { status: 'cancelada' }); msg(numero, 'Meta *' + m.titulo + '* apagada.'); continue; }
    const v = num(a.valor, 0);
    if (v === 0) { msg(numero, 'Quanto você guardou?'); continue; }
    const novo = Math.max(0, Number(m.valor_atual || 0) + v);
    const fim = novo >= Number(m.valor_alvo);
    pat('dyno_metas', m.id, autor, { valor_atual: novo, status: fim ? 'concluida' : 'ativa' });
    msg(numero, fim ? '🎉 Meta *' + m.titulo + '* concluída! Você chegou a ' + brl(novo) + '. Parabéns!' : '✅ Guardado. ' + linhaMeta(Object.assign({}, m, { valor_atual: novo })).slice(2));
    continue;
  }
  if (t === 'ver_metas') {
    const mine = metas.filter(m => aut(m) === autor);
    msg(numero, mine.length ? '🎯 *Suas metas*' + NL + mine.map(linhaMeta).join(NL) : 'Você ainda não tem metas. Diga, por exemplo: "meta viagem 5000 até dezembro".');
    continue;
  }

  // ---------- Agenda ----------
  if (t === 'criar_compromisso') {
    const ini = parseDt(a.inicio), tit = String(a.titulo || '').trim().slice(0, 150);
    if (!tit || !ini) { msg(numero, 'Me diga o que é e quando. Ex.: "dentista quinta às 15h".'); continue; }
    if (ini < agora) { msg(numero, 'Esse horário já passou. Pode confirmar o dia e a hora?'); continue; }
    const fimD = parseDt(a.fim) || ini.plus({ hours: 1 });
    const conf = compromissos.filter(k => aut(k) === autor && k.status === 'ativo').filter(k => { const i2 = dt(k.inicio), f2 = k.fim ? dt(k.fim) : i2.plus({ hours: 1 }); return ini < f2 && fimD > i2; });
    rpc('dyno_compromisso_criar', { p: { autor, titulo: tit, inicio: ini.toUTC().toISO(), fim: a.fim ? fimD.toUTC().toISO() : '', local: a.local ? String(a.local).slice(0, 120) : '', lembrar_min: num(a.lembrar_min, 60) } });
    let s = '📅 Agendado: *' + tit + '* — ' + DS[ini.weekday - 1] + ' ' + fmtDH(ini) + (a.local ? ' (' + a.local + ')' : '') + '. Aviso ' + num(a.lembrar_min, 60) + ' min antes.';
    if (conf.length) s += NL + '⚠️ Atenção: conflita com ' + conf.map(k => '*' + k.titulo + '* (' + fmtDH(dt(k.inicio)) + ')').join(', ') + '.';
    msg(numero, s);
    continue;
  }
  if (t === 'editar_compromisso' || t === 'cancelar_compromisso') {
    const k = compromissos.find(x => Number(x.id) === Number(a.id) && aut(x) === autor);
    if (!k) { msg(numero, 'Não achei esse compromisso.'); continue; }
    if (t === 'cancelar_compromisso') { rpc('dyno_compromisso_alterar', { p: { id: k.id, autor, acao: 'cancelar' } }); msg(numero, 'Compromisso *' + k.titulo + '* cancelado.'); continue; }
    const ini = a.inicio ? parseDt(a.inicio) : null;
    if (a.inicio && !ini) { msg(numero, 'Não entendi o novo horário.'); continue; }
    const p = { id: k.id, autor, acao: 'editar', titulo: a.titulo ? String(a.titulo) : '', local: a.local ? String(a.local) : '', lembrar_min: num(a.lembrar_min, 60) };
    if (ini) p.inicio = ini.toUTC().toISO();
    rpc('dyno_compromisso_alterar', { p });
    msg(numero, 'Compromisso atualizado: *' + (a.titulo || k.titulo) + '* — ' + fmtDH(ini || dt(k.inicio)) + '.');
    continue;
  }
  if (t === 'ver_agenda') {
    // 08/10: a agenda junta compromissos, tarefas com prazo, contas a vencer e lembretes (recorrentes diários viram uma linha só).
    const dias = Math.max(1, Math.min(31, Math.round(num(a.dias, 1))));
    const d0 = a.data && parseDt(a.data) ? parseDt(a.data).startOf('day') : hoje;
    const d1 = d0.plus({ days: dias });
    const dentro = d => d && d.isValid && d >= d0 && d < d1;
    const ks = compromissos.filter(k => aut(k) === autor && k.status === 'ativo' && dentro(dt(k.inicio)));
    const ts = tarefas.filter(x => aut(x) === autor && x.prazo && dentro(dt(x.prazo)));
    const cs = contas.filter(x => aut(x) === autor && x.vencimento && dentro(dt(x.vencimento)));
    const titulos = ks.map(k => norm(k.titulo));
    const ev = [];
    for (const k of ks) ev.push({ d: dt(k.inicio), h: true, s: '📅 ' + k.titulo + (k.local ? ' (' + k.local + ')' : '') });
    for (const x of ts) ev.push({ d: dt(x.prazo), h: false, s: '📋 Tarefa: ' + x.titulo });
    for (const x of cs) ev.push({ d: dt(x.vencimento), h: false, s: '💸 Conta: ' + (x.descricao || x.beneficiario || 'conta') + (x.valor ? ' — ' + brl(x.valor) : '') });
    const diarios = [];
    for (const l of lembretes.filter(l => aut(l) === autor && !l.conta_id)) {
      const tx = String(l.texto || '').split(NL)[0];
      if (/^compromisso:/i.test(tx) || titulos.some(tt => tt && norm(tx).includes(tt))) continue;
      let q = dt(l.quando);
      if (!q.isValid) continue;
      if (l.recorrencia === 'diaria' && dias > 1) { if (q < d1) diarios.push(q.toFormat('HH:mm') + ' ' + tx); continue; }
      const passo = l.recorrencia === 'semanal' ? { weeks: 1 } : l.recorrencia === 'mensal' ? { months: 1 } : l.recorrencia === 'diaria' ? { days: 1 } : null;
      if (passo) { while (q < d0) q = q.plus(passo); }
      let n = 0;
      while (dentro(q) && n < 40) { ev.push({ d: q, h: true, s: '⏰ ' + tx }); n++; if (!passo) break; q = q.plus(passo); }
    }
    ev.sort((x, y) => x.d - y.d);
    const rotulo = dias === 1 ? (d0.equals(hoje) ? 'hoje' : d0.toFormat('dd/LL')) : d0.toFormat('dd/LL') + ' a ' + d1.minus({ days: 1 }).toFormat('dd/LL');
    if (!ev.length && !diarios.length) { msg(numero, '📅 Nada na agenda para ' + rotulo + '.'); continue; }
    let s = '📅 *Agenda — ' + rotulo + '*';
    for (const e of ev) { const pre = ((dias > 1 ? DS[e.d.weekday - 1] + ' ' + e.d.toFormat('dd/LL') + ' ' : '') + (e.h ? e.d.toFormat('HH:mm') : '')).trim(); s += NL + '• ' + (pre ? pre + ' — ' : '') + e.s; }
    if (diarios.length) s += NL + NL + '🔁 *Todo dia:* ' + diarios.join('; ');
    msg(numero, s);
    continue;
  }
}
return out;

// Quem fala: agenda, listas, tarefas, compromissos e documentos = Dina; dinheiro = Dyno.
const DINA = new Set(['nota', 'ver_tarefas', 'definir_projeto', 'editar_lembrete', 'editar_tarefa', 'apagar_tarefa', 'editar_nota', 'criar_compromisso', 'editar_compromisso', 'cancelar_compromisso', 'ver_agenda', 'salvar_documento', 'ver_documentos', 'apagar_documento']);
let acts = [];
try { acts = $('Receber ação').all().map(i => i.json || {}); } catch (e) { acts = []; }
const rotina = acts.some(a => a.rotina);
const tipos = acts.map(a => String((a.a || {}).tipo || '')).filter(Boolean);
const soDina = tipos.length > 0 && tipos.every(t => DINA.has(t));
return $input.all().map(i => ({ json: { ...i.json, voz: rotina ? (/tarefa/i.test(String(i.json.texto || '')) ? 'dina' : 'dyno') : (soDina ? 'dina' : 'dyno') } }));

// 07/10/2026: gravação falhou depois de a Dina/Dyno já ter confirmado. Avisa a pessoa e o Daniel.
const ZW = String.fromCharCode(8203);
const NL = String.fromCharCode(10);
const ADMIN = '5511930851325';
let numero = '', autor = '', inst = 'dyno', rotina = false;
try { const r = $('Receber ação').first().json || {}; numero = String(r.numero || ''); autor = String(r.autor || ''); inst = String(r.instancia || 'dyno'); rotina = r.rotina === true; } catch (e) { }
const itens = $input.all();
const oque = Array.from(new Set(itens.map(i => { const j = i.json || {}; return j.tabela ? String(j.tabela).replace('dyno_', '') : (j.fn ? String(j.fn).replace('dyno_', '') : String(j.op || 'registro')); }))).join(', ');
const erro = itens.map(i => { const e = (i.json || {}).error; return e ? String(e.message || e.description || JSON.stringify(e)).slice(0, 200) : ''; }).filter(Boolean).join(' | ');
const out = [];
if (numero && inst === 'dyno' && !rotina) out.push({ json: { corpo: { number: numero, text: ZW + '⚠️ Ops, não consegui gravar isso agora por uma falha técnica (' + oque + '). Pode repetir daqui a pouco? Desculpe o transtorno.', delay: 600 } } });
out.push({ json: { corpo: { number: ADMIN, text: ZW + '⚠️ *Dyno (extras): falha ao gravar* ' + oque + ' de ' + (autor || '?') + ' (' + numero + ')' + NL + (erro || 'sem detalhe'), delay: 300 } } });
return out;

// 08/10/2026: Documentos e vencimentos (salvar, ver, apagar). Passa adiante tudo do "Processar novas funções" e acrescenta os itens novos.
const TZ = 'America/Sao_Paulo';
const NL = String.fromCharCode(10);
const hoje = DateTime.now().setZone(TZ).startOf('day');
const out = $input.all().slice();
let nd = {};
try { nd = $('Carregar dados novos').first().json || {}; } catch (e) { nd = {}; }
const documentos = Array.isArray(nd.documentos) ? nd.documentos : [];
const aut = r => r.autor || 'Daniel';
const diaIso = v => { if (!v) return null; const d = DateTime.fromISO(String(v).slice(0, 10), { zone: TZ }); return d.isValid ? d.startOf('day') : null; };
const msg = (numero, texto) => out.push({ json: { op: 'msg', numero, texto } });
const rpc = (fn, args) => out.push({ json: { op: 'rpc_sb', fn, args } });
const itens = [];
try { for (const x of $('Receber ação').all()) if (x && x.json) itens.push(x.json); } catch (e) { }
for (const it of itens) {
  if (it.rotina) continue;
  const numero = it.numero;
  const autor = it.autor || 'Daniel';
  const a = it.a || {};
  const t = String(a.tipo || '');
  if (t === 'salvar_documento') {
    const venc = diaIso(a.vencimento);
    if (!venc) { msg(numero, 'Qual é a data de validade? Me diga no formato dia/mês/ano que eu guardo.'); continue; }
    const TIPOS = ['cnh', 'rg', 'passaporte', 'visto', 'seguro', 'contrato', 'garantia', 'certificado', 'outro'];
    const doc = TIPOS.includes(String(a.documento || '').toLowerCase()) ? String(a.documento).toLowerCase() : 'outro';
    const desc = String(a.descricao || '').replace(/\d[\d.\-\/ ]{4,}\d/g, '•••').trim().slice(0, 120) || doc.toUpperCase();
    const ja = documentos.find(x => aut(x) === autor && a.id && Number(x.id) === Number(a.id));
    rpc('dyno_documento_salvar', { p: { autor, documento: doc, descricao: desc, vencimento: venc.toISODate(), id: ja ? ja.id : '', arquivo_url: String(it.arquivo || '').indexOf('sb://') === 0 ? it.arquivo : '' } });
    const MARC = { passaporte: [90, 30, 7], visto: [90, 30, 7], cnh: [60, 30, 7], rg: [60, 30] };
    const mc = MARC[doc] || [30, 7];
    const dias = Math.round(venc.diff(hoje, 'days').days);
    let s = '🗂️ ' + (ja ? 'Atualizei' : 'Guardei') + ': *' + desc + '* — validade ' + venc.toFormat('dd/LL/yyyy') + '.';
    if (dias < 0) s += NL + '⚠️ Essa data já passou. Se já renovou, me manda a nova validade.';
    else { const ant = mc.filter(m => m < dias); s += NL + 'Vou te avisar ' + (ant.length ? ant.join(', ').replace(/, (\d+)$/, ' e $1') + ' dias antes e no dia' : 'no dia') + '.'; }
    if (it.arquivo && ['cnh', 'rg', 'passaporte', 'visto'].includes(doc)) s += NL + '🔒 Por segurança, não repito números do documento aqui na conversa.';
    msg(numero, s);
    continue;
  }
  if (t === 'ver_documentos') {
    const mine = documentos.filter(x => aut(x) === autor).sort((x, y) => String(x.vencimento).localeCompare(String(y.vencimento)));
    if (!mine.length) { msg(numero, '🗂️ Você ainda não tem documentos com validade guardados. Mande a foto da CNH, do passaporte ou a nota fiscal com garantia, ou diga: "minha CNH vence em 10/05/2027".'); continue; }
    const lin = mine.map(x => { const v = diaIso(x.vencimento); const dd = Math.round(v.diff(hoje, 'days').days); return '• *' + x.descricao + '* — ' + v.toFormat('dd/LL/yyyy') + (dd < 0 ? ' (vencido)' : dd <= 60 ? ' (faltam ' + dd + ' dias)' : ''); });
    msg(numero, '🗂️ *Seus documentos e validades*' + NL + lin.join(NL));
    continue;
  }
  if (t === 'apagar_documento') {
    const x = documentos.find(y => Number(y.id) === Number(a.id) && aut(y) === autor);
    if (!x) { msg(numero, 'Não achei esse documento. Peça "meus documentos" para ver a lista.'); continue; }
    rpc('dyno_documento_apagar', { p: { autor, id: x.id } });
    msg(numero, 'Pronto, tirei *' + x.descricao + '* da lista. Não vou mais avisar sobre ele.');
    continue;
  }
}
return out;
